const techRows = $('Lay Technical Signals').all().map(i => i.json);
const symbolList = techRows.map(r => r.symbol);

const CHUNK_SIZE = 5;
const chunks = [];
for (let i = 0; i < symbolList.length; i += CHUNK_SIZE) {
  chunks.push(symbolList.slice(i, i + CHUNK_SIZE));
}

return chunks.map((chunk, idx) => ({ json: { chunk_index: idx, symbols: chunk } }));

const chunk = $('Loop Over Chunks').first().json;
const symbolList = chunk.symbols;

const techRows = $('Lay Technical Signals').all().map(i => i.json);
const sentimentRow = $('Lay Sentiment Gan Nhat').first() ? $('Lay Sentiment Gan Nhat').first().json : null;
const macroRow = $('Lay Macro Gan Nhat').first() ? $('Lay Macro Gan Nhat').first().json : null;

const techBySymbol = {};
for (const t of techRows) techBySymbol[t.symbol] = t;

const sentimentText = sentimentRow
  ? `${sentimentRow.signal} (confidence ${sentimentRow.confidence}) - ${sentimentRow.reason}`
  : 'Chua co danh gia Sentiment';
const macroText = macroRow
  ? `${macroRow.signal} (confidence ${macroRow.confidence}) - ${macroRow.reason}`
  : 'Chua co danh gia Macro';

const techLines = symbolList.map(sym => {
  const t = techBySymbol[sym];
  if (!t) return `${sym}: (chua co du lieu Technical)`;
  return `${sym}: Technical Agent noi ${t.signal} (confidence ${t.confidence}) - ${t.reason}`;
});

const prompt = `Ban la Investment Committee (Manager AI) cua mot quy dau tu crypto nho.\nBan nhan duoc 3 y kien tu 3 chuyen gia khac nhau:\n\n1. TECHNICAL AGENT (phan tich gia tung coin):\n${techLines.join('\n')}\n\n2. SENTIMENT AGENT (tam ly thi truong chung):\n${sentimentText}\n\n3. MACRO AGENT (boi canh vi mo chung):\n${macroText}\n\nHay dua ra QUYET DINH CUOI CUNG cho tung coin, ket hop ca 3 y kien tren. Neu Sentiment/Macro tieu cuc manh, co the ha thap confidence cua tin hieu Technical du Technical dang lac quan (va nguoc lai).\n\nTra loi DUY NHAT mot JSON array, khong markdown, dung format:\n[{"symbol": "BTCUSDT", "final_signal": "BUY|SELL|HOLD", "final_confidence": 0-100, "reason": "giai thich ngan gon dua tren ca 3 y kien"}]\n\nPhai co du 1 object cho moi symbol: ${symbolList.join(', ')}`;

return [{ json: { prompt, symbol_list: symbolList } }];

const raw = $input.first().json;
const symbolList = $('Build Committee Prompt').first().json.symbol_list;
const techRows = $('Lay Technical Signals').all().map(i => i.json);
const sentimentRow = $('Lay Sentiment Gan Nhat').first() ? $('Lay Sentiment Gan Nhat').first().json : null;
const macroRow = $('Lay Macro Gan Nhat').first() ? $('Lay Macro Gan Nhat').first().json : null;
const techBySymbol = {};
for (const t of techRows) techBySymbol[t.symbol] = t;

let contentText = '';
if (raw.choices && raw.choices[0] && raw.choices[0].message) {
  contentText = raw.choices[0].message.content || '';
}
const cleaned = contentText.replace(/```json|```/g, '').trim();

let parsed;
try { parsed = JSON.parse(cleaned); } catch (e) { parsed = []; }

if (parsed && !Array.isArray(parsed) && typeof parsed === 'object') {
  parsed = Object.entries(parsed).map(([key, val]) => ({
    symbol: (val && val.symbol) || key,
    final_signal: val ? val.final_signal : undefined,
    final_confidence: val ? val.final_confidence : undefined,
    reason: val ? val.reason : undefined
  }));
}

if (!Array.isArray(parsed) || parsed.length === 0) {
  parsed = symbolList.map(symbol => ({
    symbol, final_signal: 'HOLD', final_confidence: 0, reason: 'parse_error: AI khong tra ve JSON hop le'
  }));
}

return parsed.map(p => {
  const t = techBySymbol[p.symbol] || {};
  let conf = parseInt(p.final_confidence, 10);
  if (isNaN(conf)) conf = null;
  return { json: {
    symbol: p.symbol,
    technical_signal: t.signal || null,
    technical_confidence: t.confidence || null,
    sentiment_signal: sentimentRow ? sentimentRow.signal : null,
    macro_signal: macroRow ? macroRow.signal : null,
    final_signal: (p.final_signal || 'HOLD').toUpperCase(),
    final_confidence: conf,
    reason: p.reason || ''
  } };
});
